Method.Source:
/// <summary>
/// PaffH 10.12.21
/// </summary>
/// <param name = "_logActivity">NDXLogActivity</param>
/// <param name = "_counter">Counter</param>
/// <returns>NDXLogActivity</returns>
public NDXLogActivity parmLogActivity(NDXLogActivity _logActivity = logActivity, Counter _counter = 0)
{
    logActivity = _logActivity;
    if (!prmIsDefault(_counter))
    {
        this.parmCounter(_counter);
    }
    return logActivity;
}
